import * as THREE from 'three/webgpu';
import { color, mix, dot, normalize, transformNormalToView, positionViewDirection, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-badge';

  const pos = config.scenePlacement?.position || { x: 2.5, y: -0.2, z: 0 };
  const rot = config.scenePlacement?.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scenePlacement?.scale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const accentColor = new THREE.Color('#ff2a38');
  const inkColor = new THREE.Color('#16161d');

  const capsuleGroup = new THREE.Group();
  group.add(capsuleGroup);

  let meshObject = null;
  let rimMaterials = [];

  const meshUrl = '/prism-mock/orrery/meshes/gear-a.glb';
  const gltf = ctx.glbLoader.load(meshUrl);

  function applyRimShading(root) {
    root.traverse((child) => {
      if (child.isMesh && child.material) {
        const baseMat = child.material;
        const fresnelUniform = uniform(1.5);

        const viewDir = positionViewDirection;
        const nrm = transformNormalToView(child.geometry.attributes.normal ? undefined : undefined);
        const fresnel = float(1.0).sub(dot(normalize(viewDir), normalize(nrm || viewDir))).pow(fresnelUniform);

        baseMat.emissiveNode = mix(color(inkColor), color(accentColor), fresnel);
        baseMat.metalness = Math.min(baseMat.metalness ?? 0.5, 0.55);
        baseMat.roughness = Math.max(baseMat.roughness ?? 0.6, 0.5);
        if ('clearcoat' in baseMat) baseMat.clearcoat = Math.min(baseMat.clearcoat ?? 0.2, 0.25);
        baseMat.needsUpdate = true;
        rimMaterials.push(baseMat);
      }
    });
  }

  if (gltf && gltf.scene) {
    meshObject = gltf.scene.clone();
    meshObject.scale.setScalar(0.35);
    applyRimShading(meshObject);
    capsuleGroup.add(meshObject);
  }

  // fallback capsule shell placeholder (small, in case mesh not ready visually)
  const capsuleGeo = new THREE.CapsuleGeometry(0.12, 0.28, 4, 12);
  const capsuleMat = new THREE.MeshStandardNodeMaterial();
  capsuleMat.color = new THREE.Color('#e8ecf2');
  capsuleMat.metalness = 0.5;
  capsuleMat.roughness = 0.55;
  if ('clearcoat' in capsuleMat) capsuleMat.clearcoat = 0.2;
  capsuleMat.emissiveNode = color(accentColor).mul(0.15);
  const capsuleMesh = new THREE.Mesh(capsuleGeo, capsuleMat);
  capsuleMesh.rotation.z = Math.PI / 2;
  capsuleMesh.visible = false;
  capsuleGroup.add(capsuleMesh);

  // accent rim light edge
  const rimLight = new THREE.PointLight(new THREE.Color('#ff2a38'), 0.6, 2.0);
  rimLight.position.set(0.15, 0, 0.3);
  group.add(rimLight);

  // apply cinematic primitives
  const primitivesConfig = config.cinematicPrimitives || [
    { name: 'parallax-scroll', params: { intensity: 0.4 } },
    { name: 'magnetic-cursor', params: { radius: 1.2, strength: 0.35 } },
  ];

  primitivesConfig.forEach((p) => {
    if (ctx.primitives[p.name]) {
      ctx.primitives[p.name](group, p.params);
    }
  });

  // entrance: weighted-settle
  const baseScale = { x: scl.x, y: scl.y, z: scl.z };
  group.scale.set(0.01, 0.01, 0.01);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: baseScale.x * 1.04,
    y: baseScale.y * 1.04,
    z: baseScale.z * 1.04,
    duration: 0.5,
    ease: 'power4.out',
  }).to(group.scale, {
    x: baseScale.x,
    y: baseScale.y,
    z: baseScale.z,
    duration: 0.4,
    ease: 'power4.out',
  });

  // hover: rise-in (subtle 0.15 units)
  let hoverTl = null;
  const baseY = pos.y;

  const handleHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const handleHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const handleClick = () => {
    gsap.to(group.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
      onComplete: () => {
        group.dispatchEvent({ type: 'hub-journal.select' });
      },
    });
  };

  group.userData.handlers = {
    hover: handleHoverIn,
    hoverIn: handleHoverIn,
    hoverOut: handleHoverOut,
    click: handleClick,
  };

  group.userData.cleanup = () => {
    settleTl.kill();
    if (hoverTl) hoverTl.kill();
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(group.position);

    rimMaterials.forEach((mat) => mat.dispose && mat.dispose());
    capsuleGeo.dispose();
    capsuleMat.dispose();

    if (meshObject) {
      meshObject.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material?.dispose();
          }
        }
      });
    }

    group.remove(rimLight);
    rimLight.dispose && rimLight.dispose();
  };

  return group;
}
